"""Topic-specific educational and writer material for session eight."""
TITLES=['مبدأ شریان‌های گردن و کاروتید مشترک','مجاورات و دوشاخگی کاروتید مشترک','جسم کاروتید و مسیر کاروتید داخلی','انسداد و شاخه‌های کاروتید خارجی','شاخه‌های انتهایی و تیروئیدی فوقانی','شریان زبانی و مسیر شریان صورتی','شاخه‌های صورتی، پس‌سری و گوشی خلفی','گیجگاهی سطحی و آغاز ساب‌کلاوین','شریان مهره‌ای و توراسیک داخلی','توراسیک داخلی و تنهٔ تیروسرویکال','کاستوسرویکال و شریان کتفی خلفی','اختلالات ساب‌کلاوین و وریدهای گردن']
GUIDES={
1:['منشأ کاروتید مشترک و ساب‌کلاوین را در سمت راست و چپ روی شکل دنبال کنید.','مسیر گردنی کاروتید راست را با مسیر سینه‌ای و گردنی چپ مقایسه کنید.','اوموهایوئید را نسبت به کاروتید مشترک جهت‌یابی کنید.'],
2:['ورید ژوگولار داخلی، شریان و واگ را در غلاف کاروتید از هم جدا کنید.','سطح دوشاخگی و دو شاخهٔ داخلی و خارجی را روی شکل بیابید.','سینوس کاروتید و حساسیت فشاری را از جسم کاروتید جدا بیان کنید.'],
3:['جسم کاروتید را کنار دوشاخگی پیدا و با سینوس مقایسه کنید.','چهار بخش کاروتید داخلی را از گردن تا جمجمه دنبال کنید.','شاخهٔ چشمی را از انشعاب مغزی نهایی در نمودار مرجع متمایز کنید.'],
4:['راه‌های جریان جانبی را در شکل همراه جهت و شرایط دنبال کنید.','مسیر کاروتید داخلی و خارجی را از دوشاخگی جداگانه نشان دهید.','شاخه‌های قدامی و خلفی کاروتید خارجی را نام‌گذاری کنید.'],
5:['شاخه‌های انتهایی کاروتید خارجی را در عقب گردن مندیبل پیدا کنید.','شریان تیروئیدی فوقانی را تا قطب فوقانی تیروئید دنبال کنید.','شاخه‌های تیروئیدی و ارتباط آن‌ها با عصب حنجره‌ای را تفکیک کنید.'],
6:['لینگوال را نسبت به شاخ بزرگ لامی و عضله هایوگلوس مشخص کنید.','شریان فاسیال را از کاروتید خارجی تا کنار مندیبل و زاویهٔ چشم دنبال کنید.','دو دستهٔ شاخه‌های گردنی و صورتی را از مسیر اصلی جدا بنویسید.'],
7:['شاخه‌های گردنی و صورتی فاسیال را با مسیر و مقصدشان مشخص کنید.','اکسیپیتال و گوشی خلفی را نسبت به بطن خلفی دیگاستریک مقایسه کنید.','مسیر شاخهٔ استایلوماستوئید را با ساختارهای مرتبط بخوانید.'],
8:['تمپورال سطحی و شاخه‌های فرونتال، پاریتال و عرضی صورت را پیدا کنید.','مبدأ ساب‌کلاوین چپ و راست را مقایسه کنید.','سه بخش ساب‌کلاوین را نسبت به اسکالن قدامی جهت‌یابی کنید.'],
9:['چهار قسمت شریان ورتبرال را از ساب‌کلاوین تا بازیلار دنبال کنید.','سوراخ عرضی، قوس خلفی اطلس و فورامن مگنوم را جدا نشان دهید.','توراسیک داخلی را تا مسیر کنار جناغ در شکل مشخص کنید.'],
10:['مسیر و شاخه‌های انتهایی توراسیک داخلی را در تصویر دنبال کنید.','سه شاخهٔ اصلی توصیف‌شده برای تیروسرویکال را از شاخهٔ گردنی صعودی جدا کنید.','مجاورت تیروئیدی تحتانی با واگ، تنهٔ سمپاتیک و عصب راجعه را با مرجع تطبیق دهید.'],
11:['منشأ تنهٔ کاستوسرویکال راست و چپ را با قید تنوع مقایسه کنید.','شاخهٔ عمقی گردن را از بین‌دنده‌ای فوقانی و مسیرشان جدا کنید.','دورسال اسکاپولار را در رابطه با شبکهٔ بازویی و لواتور دنبال کنید.'],
12:['مسیر جریان معکوس در پدیدهٔ ساب‌کلاوین استیل را گام‌به‌گام توضیح دهید.','ورید ژوگولار داخلی را از سیگموئید تا محل اتصال به ساب‌کلاوین دنبال کنید.','وریدهای سطحی قدامی و خارجی را از ژوگولار داخلی تفکیک کنید.']}
QUESTIONS={i:'؛ '.join(g.rstrip(' .') for g in v[:2])+'؟' for i,v in GUIDES.items()}
REVIEW={1:'منشأ راست و چپ و سطح عبور اوموهایوئید را با شکل ۸.۱۶۵ گری مقایسه کنید.',2:'واگ درون غلاف و پشتِ بین شریان و ورید قرار دارد؛ روابط با توصیف منبع مقایسه شود.',3:'توصیف منبع دربارهٔ ماساژ و سه شاخهٔ انتهایی با توضیح مستقل و طرح نتر مقایسه شود؛ ماساژ گردن دستور عملی نیست.',4:'نام شریان بینی در دو توصیف منبع و مسیر آناستوموز نتر مقایسه شود؛ تظاهر انسداد و کفایت مسیرهای جانبی متغیرند.',5:'مبدأ و تقسیم شاخه‌ها را با جدول ۸.۱۳ گری و پلیت ۵۸ نتر تطبیق دهید.',6:'در حاشیهٔ منبع دربارهٔ سوپراهیوئید/اینفراهیوئید تردید ذکر شده؛ شکل و مرجع بررسی شوند. متن مداخلهٔ بالینی دستور عملی نیست.',7:'نام‌های شاخه و روابط فضایی را با شکل‌ها و پلیت ۹۹ نتر مقایسه کنید؛ متن اصل حفظ شده است.',8:'عبارت منبع دربارهٔ نبض میگرن حکم تشخیصی یا برای همهٔ موارد نیست؛ بخش‌های ساب‌کلاوین با گری مقایسه شوند.',9:'عبارت «داخل عضله» در صفحهٔ ۹ با تقسیم داخلی/پشتی/خارجی نسبت به عضله در صفحهٔ ۸ و گری تطبیق شود.',10:'مجاورت عصب راجعه و مسیر تیروئیدی تحتانی با تصویر مرجع بررسی شود؛ تنوع فردی را حذف نکنید.',11:'سمت و محل منشأ کاستوسرویکال و دورسال اسکاپولار می‌توانند متفاوت باشند؛ متن منبع و شرح گری جدا بمانند.',12:'وجود دندهٔ گردنی الزاماً علامت ایجاد نمی‌کند؛ برگشت جریان با سندرم علامت‌دار یکی نیست. اتصال وریدها با گری بررسی شود.'}
NOTES={1:('گری منشأ راست را تنهٔ براکیوسفالیک و منشأ چپ را قوس آئورت نشان می‌دهد؛ تفاوت مسیر سینه‌ای و گردنی را از تفاوت نام شریان جدا کنید.','گری، آناتومی برای دانشجویان، ویراست ۳، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۳۸، چاپی ۱۰۱۰، شکل ۸.۱۶۵'),2:('در گری ورید ژوگولار داخلی در گردن خارج شریان مشترک و واگ در پشت و تا حدی بین دو رگ توصیف می‌شود؛ مجاورت با عصب مساوی یکسان‌بودن ساختارهای درون و پشت غلاف نیست.','گری، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۴۱، چاپی ۱۰۱۳'),3:('در طرح نتر شریان افتالمیک پیش از تقسیم نهایی کاروتید داخلی جدا می‌شود؛ آن را همراه دو شاخهٔ مغزی به‌صورت سه شاخهٔ انتهایی هم‌تراز نخوانید. در گری، سینوس گیرندهٔ فشار با عصب‌رسانی شاخهٔ IX است؛ بیان منبع دربارهٔ تحریک سمپاتیک و تنگی عروق به‌تنهایی توضیح قابل اتکای این رفلکس نیست. ماساژ گردن می‌تواند خطرناک باشد و توصیه نمی‌شود.','نتر، اطلس آناتومی انسان، ویراست ۸، پلیت ۱۶۵، صفحهٔ فایل ۲۱۷؛ گری، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۳۹، چاپی ۱۰۱۱'),4:('طرح نتر اتصال زاویه‌ای و شاخهٔ دورسال بینی را نشان می‌دهد. این ارتباط بالقوه به معنی کفایت همیشگی جریان جانبی یا وقوع حتمی هر علامت نیست.','نتر، پلیت ۱۶۵، صفحهٔ فایل ۲۱۷'),5:('گری تیروئیدی فوقانی، حلقی صعودی، زبانی، صورتی، پس‌سری، گوشی خلفی و دو شاخهٔ انتهایی را جداگانه شرح می‌دهد؛ جهت و منشأ شکل را با فهرست مقایسه کنید.','گری، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۴۰، چاپی ۱۰۱۲، شکل ۸.۱۶۷ و جدول ۸.۱۳؛ صفحهٔ فایل ۴۱، چاپی ۱۰۱۳'),6:('در تصویر نتر مسیر لینگوال و فاسیال و رابطهٔ آن‌ها با عضلات و لامی دیده می‌شود. پلیت ۱۰۳ نتر شاخهٔ اینفراهیوئید را نشان می‌دهد، در حالی که جزوه دربارهٔ سوپراهیوئید نوشته است. عبارت بالینی جزوه راهنمای بستن رگ یا درمان خون‌ریزی نیست.','نتر، پلیت ۵۸، صفحهٔ فایل ۱۱۰؛ پلیت ۹۹، صفحهٔ فایل ۱۵۱؛ پلیت ۱۰۳، صفحهٔ فایل ۱۵۵'),7:('شکل مرجع شاخه‌های صورتی، پس‌سری و گوشی خلفی را در یک نمای طرفی نشان می‌دهد؛ نام رگ، عضلهٔ مجاور و ساختار هدف را از هم تفکیک کنید.','نتر، پلیت ۹۹، صفحهٔ فایل ۱۵۱'),8:('گری بخش اول را تا لبهٔ داخلی اسکالن قدامی، بخش دوم را در پشت عضله و بخش سوم را خارج آن توصیف می‌کند. متن منبع دربارهٔ نبض در میگرن به‌تنهایی آزمون تشخیصی نیست.','گری، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۵۴، چاپی ۱۰۲۶؛ شکل ۸.۱۸۲'),9:('در قرارداد گری بخش اول ساب‌کلاوین در سمت داخلی اسکالن قدامی است، نه داخل بافت عضله. مسیر شریان مهره‌ای و محل ورود به سوراخ‌های عرضی را با شکل تطبیق دهید.','گری، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۵۴، چاپی ۱۰۲۶؛ صفحهٔ فایل ۵۹، چاپی ۱۰۳۱، شکل ۸.۱۸۷'),10:('رابطهٔ عصب راجعه و شریان تیروئیدی تحتانی را در نمای خلفی بخوانید؛ محل عصب و شاخه‌ها می‌تواند تنوع داشته باشد و تصویر جایگزین تصمیم‌گیری بالینی نیست.','نتر، پلیت ۱۰۴، صفحهٔ فایل ۱۵۶'),11:('گری می‌گوید دورسال اسکاپولار ممکن است از بخش سوم ساب‌کلاوین منشأ بگیرد؛ این عبارت وجود تنوع منشأ را نفی نمی‌کند.','گری، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۵۴، چاپی ۱۰۲۶'),12:('ژوگولار داخلی با ورید ساب‌کلاوین در هر طرف به هم می‌پیوندند و براکیوسفالیک را تشکیل می‌دهند؛ آن‌ها را سه مرحله از یک نام واحد فرض نکنید. وجود دندهٔ گردنی الزاماً به علائم منجر نمی‌شود.','گری، بخش ۱۰۰۱–۱۱۸۹، صفحهٔ فایل ۴۱، چاپی ۱۰۱۳؛ شکل ۸.۱۶۵، صفحهٔ فایل ۳۸، چاپی ۱۰۱۰')}
